export async function handle(db, request) {
  await db.lock("count-lock");
  try {
    const before = await db.get("count");
    await db.set("count", before + request.delta);
    await db.append("applied", { requestId: request.id, delta: request.delta });
    return { applied: true };
  } finally {
    await db.unlock("count-lock");
  }
}

